import TextInput from "@marko-ui/shadcn/ui/input/input.marko";
import Label from "@marko-ui/shadcn/ui/label/label.marko";

<div class="grid w-full max-w-sm items-center gap-3">
  <Label for="email">Email</Label>
  <TextInput type="email" id="email" placeholder="Email"/>
</div>

import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";

<Field class="max-w-sm">
  <FieldLabel for="field-default-email">Email</FieldLabel>
  <TextInput id="field-default-email" type="email" placeholder="you@example.com"/>
  <FieldDescription>We'll never share your email.</FieldDescription>
</Field>
